def generate_N_cycle(ji, N, cycle):
    output = []
    for i in range(17):
        row = []
        for j in range(17):
            if ji == "sum":
                idx = (i + j) % N
            else:
                idx = (j - i) % N
            row.append(cycle[idx])
        output.append(row)
    return output

